Repair the complete CommonJS source below. It should export `{ radialLayout }`. The function accepts an array of plain objects with exactly `{ id, angleDegrees, radius, kind }`. IDs are unique non-empty strings; angles are finite numbers normalized modulo 360; radius is finite and non-negative; kind is one of `"sensor"`, `"relay"`, or `"hub"`. Return fresh frozen points `{ id, x, y, glyph }` in input order, where x=radius*cos(angle) and y=radius*sin(angle), angle is interpreted in degrees, and glyph maps to `"o"`, `"s"`, or `"*"`. Normalize values whose absolute magnitude is below 1e-12 to zero. Empty input returns a frozen empty array. Malformed data throws `TypeError`, invalid ranges or duplicate IDs throw `RangeError`, and input is not mutated. Return a corrected complete source file.

```javascript
function radialLayout(devices) {
  if (!Array.isArray(devices)) throw new TypeError('devices must be an array');
  const ids = new Set();
  const glyphs = { sensor: 'o', relay: 's', hub: '*' };
  const points = devices.map(device => {
    if (!device || typeof device !== 'object' || Array.isArray(device) || Object.getPrototypeOf(device) !== Object.prototype) throw new TypeError('device must be plain');
    const keys = Object.keys(device).sort();
    const expected = ['angleDegrees', 'id', 'kind', 'radius'];
    if (keys.length !== expected.length || keys.some((key, i) => key !== expected[i])) throw new TypeError('invalid fields');
    if (typeof device.id !== 'string' || device.id.length === 0) throw new TypeError('invalid id');
    if (ids.has(device.id)) throw new RangeError('duplicate id');
    if (typeof device.angleDegrees !== 'number' || !Number.isFinite(device.angleDegrees)) throw new TypeError('invalid angle');
    if (typeof device.radius !== 'number' || !Number.isFinite(device.radius)) throw new TypeError('invalid radius');
    if (device.radius < 0) throw new RangeError('negative radius');
    if (!Object.hasOwn(glyphs, device.kind)) throw new TypeError('invalid kind');
    ids.add(device.id);
    const angle = ((device.angleDegrees % 360) + 360) % 360;
    let x = device.radius * Math.cos(angle);
    let y = device.radius * Math.sin(angle);
    if (Math.abs(x) < 1e-12) x = 0;
    if (Math.abs(y) < 1e-12) y = 0;
    return Object.freeze({ id: device.id, x, y, glyph: glyphs[device.kind] });
  });
  return Object.freeze(points);
}

module.exports = { radialLayout };
```

