'use strict';
const assert = require('node:assert');
const { radialLayout } = require('./solution');

assert.deepStrictEqual(Object.keys(require('./solution')), ['radialLayout']);
const empty = radialLayout([]);
assert.deepStrictEqual(empty, []);
assert.ok(Object.isFrozen(empty));

const devices = [
  { id: 'east', angleDegrees: 0, radius: 2, kind: 'sensor' },
  { id: 'north', angleDegrees: 90, radius: 3, kind: 'relay' },
  { id: 'west', angleDegrees: 540, radius: 4, kind: 'hub' },
  { id: 'south', angleDegrees: -90, radius: 5, kind: 'sensor' },
  { id: 'origin', angleDegrees: 33, radius: 0, kind: 'hub' }
];
const original = JSON.parse(JSON.stringify(devices));
const points = radialLayout(devices);
assert.deepStrictEqual(points, [
  { id: 'east', x: 2, y: 0, glyph: 'o' },
  { id: 'north', x: 0, y: 3, glyph: 's' },
  { id: 'west', x: -4, y: 0, glyph: '*' },
  { id: 'south', x: 0, y: -5, glyph: 'o' },
  { id: 'origin', x: 0, y: 0, glyph: '*' }
]);
assert.deepStrictEqual(devices, original);
assert.ok(Object.isFrozen(points));
for (const point of points) assert.ok(Object.isFrozen(point));
assert.throws(() => points.push({}), TypeError);
assert.throws(() => { points[0].x = 9; }, TypeError);

const diagonal = radialLayout([{ id: 'd', angleDegrees: 45, radius: Math.sqrt(2), kind: 'relay' }])[0];
assert.ok(Math.abs(diagonal.x - 1) < 1e-12);
assert.ok(Math.abs(diagonal.y - 1) < 1e-12);

assert.throws(() => radialLayout(null), TypeError);
assert.throws(() => radialLayout([devices[0], { ...devices[0] }]), RangeError);
assert.throws(() => radialLayout([{ ...devices[0], id: '' }]), TypeError);
assert.throws(() => radialLayout([{ ...devices[0], angleDegrees: Infinity }]), TypeError);
assert.throws(() => radialLayout([{ ...devices[0], radius: '2' }]), TypeError);
assert.throws(() => radialLayout([{ ...devices[0], radius: -1 }]), RangeError);
assert.throws(() => radialLayout([{ ...devices[0], kind: 'other' }]), TypeError);
assert.throws(() => radialLayout([{ ...devices[0], extra: true }]), TypeError);
assert.throws(() => radialLayout([Object.assign(Object.create({ inherited: true }), devices[0])]), TypeError);

